import { Suspense } from 'react'
import { CardStats } from './CardStats'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'

function CardStatsSkeleton() {
  return (
    <div className="grid grid-cols-2 gap-4" aria-hidden>
      <div className="card">
        <div className="mb-2 h-4 w-24 animate-pulse rounded bg-gray-200" />
        <div className="h-6 w-32 animate-pulse rounded bg-gray-200" />
      </div>
      <div className="card">
        <div className="mb-2 h-4 w-24 animate-pulse rounded bg-gray-200" />
        <div className="h-6 w-32 animate-pulse rounded bg-gray-200" />
      </div>
    </div>
  )
}

function RevenueChartSkeleton() {
  return (
    <div className="chart" aria-hidden>
      <div className="mb-3 h-5 w-24 animate-pulse rounded bg-gray-200" />
      <ul className="space-y-2">
        {Array.from({ length: 6 }).map((_, i) => (
          <li
            key={i}
            className="h-4 animate-pulse rounded bg-gray-200"
            style={{ width: `${60 + (i % 3) * 10}%` }}
          />
        ))}
      </ul>
    </div>
  )
}

function LatestInvoicesSkeleton() {
  return (
    <div className="invoices" aria-hidden>
      <div className="mb-3 h-5 w-32 animate-pulse rounded bg-gray-200" />
      <ul className="space-y-2">
        {Array.from({ length: 5 }).map((_, i) => (
          <li
            key={i}
            className="h-4 animate-pulse rounded bg-gray-200"
            style={{ width: `${70 + (i % 3) * 10}%` }}
          />
        ))}
      </ul>
    </div>
  )
}

export default function Page() {
  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<CardStatsSkeleton />}>
        <CardStats />
      </Suspense>
      <Suspense fallback={<RevenueChartSkeleton />}>
        <RevenueChart />
      </Suspense>
      <Suspense fallback={<LatestInvoicesSkeleton />}>
        <LatestInvoices />
      </Suspense>
    </main>
  )
}

